<script setup>
import { ref, computed, watch, defineAsyncComponent } from 'vue'
import { useRoute } from 'vue-router'
import { driversApi } from '../../api/drivers.api'
import { useOrderPolling } from '../../composables/useOrderPolling'
import { preparationLabels, deliveryLabels, deliveryActionLabels, driverTime, driverError, isDriverOrderClosed } from '../../constants/driverDelivery'
import { formatCurrency } from '../../utils/formatters'
import { validLocation } from '../../utils/location'
import SiteIcon from '../../components/site/SiteIcon.vue'
import OrderLifecycleSummary from '../../components/orders/OrderLifecycleSummary.vue'
import DriverIntervention from '../../components/orders/DriverIntervention.vue'
const DeliveryDestinationMap = defineAsyncComponent(() => import('../../components/orders/DeliveryDestinationMap.vue'))
const route = useRoute(), busy = ref(false), error = ref(null), notice = ref(''), reason = ref(''), failureOpen = ref(false), cashOpen = ref(false), amount = ref('')
const state = useOrderPolling(signal => driversApi.order(route.params.id, signal), { paused: () => busy.value, normalizeError: driverError })
const order = state.data, readOnly = computed(() => isDriverOrderClosed(order.value)), actions = computed(() => readOnly.value ? [] : order.value?.available_actions || [])
const location = computed(() => order.value?.address?.location)
const hasLocation = computed(() => validLocation(location.value?.latitude, location.value?.longitude))
const navigation = computed(() => hasLocation.value ? 'https://www.google.com/maps/dir/?api=1&destination=' + encodeURIComponent(location.value.latitude + ',' + location.value.longitude) : '')
const mapUrl = computed(() => hasLocation.value ? 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(location.value.latitude + ',' + location.value.longitude) : '')
async function operate(status) {
  if (busy.value || readOnly.value || !actions.value.includes(status)) return
  if (status === 'delivered' && !window.confirm('هل سلّمت الطلب للعميل؟')) return
  busy.value = true; error.value = null; notice.value = ''
  try {
    order.value = await driversApi.transition(route.params.id, status, status === 'failed' ? reason.value : null)
    failureOpen.value = false; reason.value = ''; notice.value = 'تم تحديث حالة التوصيل.'
  } catch (cause) { error.value = driverError(cause); if ([401,403,404].includes(error.value.status)) order.value = null; await state.load(false, true) }
  finally { busy.value = false }
}
async function collect() {
  if (busy.value || readOnly.value || !actions.value.includes('collect_cash') || !window.confirm('تأكيد استلام ' + formatCurrency(amount.value) + ' نقدًا من العميل؟')) return
  busy.value = true; error.value = null; notice.value = ''
  try { await driversApi.collect(route.params.id, amount.value); cashOpen.value = false; notice.value = 'تم تسجيل المبلغ المحصل.'; await state.load(false, true) }
  catch (cause) { error.value = driverError(cause); if ([401,403,404].includes(error.value.status)) order.value = null; await state.load(false, true) }
  finally { busy.value = false }
}
watch(() => route.params.id, () => { state.reset(); error.value = null; notice.value = ''; failureOpen.value = cashOpen.value = false; void state.load() })
void state.load()
</script>
<template><main id="main" class="driver-main"><div class="driver-toolbar"><RouterLink class="driver-link" to="/driver/orders">العودة للطلبات</RouterLink><button class="driver-link" :disabled="busy || state.refreshing.value" @click="state.load()">تحديث</button></div><p v-if="state.loading.value" role="status">جارٍ تحميل الطلب…</p><div v-if="error || state.error.value" class="driver-error" role="alert"><p>{{ error?.message || state.error.value?.message }}</p><p v-for="(messages,key) in error?.errors" :key="key">{{ Array.isArray(messages)?messages.join(' '):messages }}</p><button class="driver-link" @click="state.load()">إعادة المحاولة</button></div><p v-if="notice" class="driver-notice" role="status">{{ notice }}</p><template v-if="order"><section class="driver-card"><div class="driver-card-head"><h1>طلب <bdi>#{{ order.order_number }}</bdi></h1><span class="driver-badge">{{ deliveryLabels[order.delivery_status] }}</span></div><dl><div><dt>حالة تجهيز الطلب</dt><dd>{{ preparationLabels[order.preparation_status] }}</dd></div><div><dt>وقت التجهيز المتوقع</dt><dd>{{ driverTime(order.estimated_ready_at) || 'غير محدد' }}</dd></div></dl><OrderLifecycleSummary :status="order.preparation_status" :delivery-status="order.delivery_status" delivery-only/><p v-if="!readOnly && order.delivery_block" class="driver-muted" role="status">{{ order.delivery_block.message }}</p><div v-if="!readOnly" class="driver-actions"><button v-if="order.delivery_status==='on_the_way' && !actions.includes('delivered')" class="driver-button" disabled>تأكيد التسليم غير متاح</button><button v-for="action in actions.filter(item=>deliveryActionLabels[item])" :key="action" class="driver-button" :disabled="busy" @click="operate(action)">{{ busy?'جارٍ التحديث…':deliveryActionLabels[action] }}</button><button v-if="actions.includes('failed')" class="driver-button secondary" :disabled="busy" @click="failureOpen=!failureOpen">تعذر التسليم</button></div><p v-if="order.delivery_status==='assigned' && order.preparation_status!=='ready'" class="driver-muted">انتظر جاهزية الطلب قبل الاستلام.</p><p v-if="order.delivery_status==='failed'" class="driver-muted">تواصل مع إدارة الفرع لمعالجة الطلب. سيبقى الطلب في عهدتك حتى المعالجة.</p><form v-if="failureOpen && !readOnly" @submit.prevent="operate('failed')"><label class="driver-field">سبب تعذر التسليم<textarea v-model="reason" required minlength="3" maxlength="1000" rows="3" :disabled="busy"/></label><button class="driver-button secondary" :disabled="busy">تسجيل تعذر التسليم</button></form></section><p v-if="order.delivery_status==='delivered'" class="driver-notice" role="status">تم تسجيل التسليم للعميل. الإكمال النهائي للطلب لدى الكاشير.</p><DriverIntervention :order="order" :reload="()=>state.load(false,true)" @active="busy=$event"/><section class="driver-card"><h2>العميل وعنوان التوصيل</h2><div class="driver-address"><p>{{ order.customer?.name }}</p><p dir="ltr">{{ order.customer?.phone }}</p><p v-if="order.address?.recipient_name && order.address.recipient_name!==order.customer?.name">المستلم: {{ order.address.recipient_name }}</p><div v-if="order.address" class="driver-address-location"><p>{{ order.address.city }}، {{ order.address.district }}، {{ order.address.street }}</p><a v-if="mapUrl && !readOnly" class="driver-button secondary driver-open-map" :href="mapUrl" target="_blank" rel="noopener noreferrer"><SiteIcon name="map-pin"/>فتح على الخريطة</a></div><p v-if="order.address?.building_number">المبنى {{ order.address.building_number }}<span v-if="order.address.floor"> · الطابق {{ order.address.floor }}</span><span v-if="order.address.apartment"> · الشقة {{ order.address.apartment }}</span></p><p v-if="order.address?.landmark">{{ order.address.landmark }}</p><p v-if="order.address?.notes">تعليمات التوصيل: {{ order.address.notes }}</p></div><DeliveryDestinationMap v-if="hasLocation" :key="order.id" :location="location" :branch="order.branch_location"/><p v-if="hasLocation" class="driver-muted">موقع التوصيل: <bdi>{{ location.latitude }}, {{ location.longitude }}</bdi></p><p v-else class="driver-muted">لم يُحدد موقع على الخريطة لهذا الطلب. استخدم العنوان واتصل بالعميل.</p><div v-if="!readOnly" class="driver-actions"><a v-if="order.customer?.phone" class="driver-button secondary" :href="'tel:'+order.customer.phone">اتصال بالعميل</a><a v-if="order.address?.phone && order.address.phone!==order.customer?.phone" class="driver-button secondary" :href="'tel:'+order.address.phone">اتصال بالمستلم</a><a v-if="navigation" class="driver-button" :href="navigation" target="_blank" rel="noopener noreferrer">فتح الملاحة</a></div></section><section class="driver-card"><h2>الدفع والتحصيل</h2><dl><div><dt>إجمالي الطلب</dt><dd>{{ formatCurrency(order.total) }}</dd></div><div><dt>رسوم التوصيل</dt><dd>{{ formatCurrency(order.delivery_fee) }}</dd></div><div><dt>طريقة الدفع</dt><dd>{{ {cash:'نقدًا',network:'الشبكة',card:'البطاقة'}[order.payment_method] }}</dd></div><div><dt>حالة الدفع</dt><dd>{{ {paid:'مدفوع',pending:'بانتظار الدفع',failed:'تعذر الدفع',cancelled:'ملغي',refunded:'مسترد',partially_refunded:'مسترد جزئيًا'}[order.payment_status] || order.payment_status }}</dd></div><div><dt>المطلوب تحصيله نقدًا</dt><dd>{{ formatCurrency(order.cash_due) }}</dd></div></dl><button v-if="actions.includes('collect_cash')" class="driver-button" :disabled="busy" @click="cashOpen=!cashOpen;amount=order.cash_due">تسجيل التحصيل النقدي</button><form v-if="cashOpen && actions.includes('collect_cash')" @submit.prevent="collect"><label class="driver-field">المبلغ المحصل فعليًا<input v-model="amount" type="number" min="0" step="0.01" required :disabled="busy" inputmode="decimal"/></label><p class="driver-muted">سجّل التحصيل بعد استلام كامل المبلغ من العميل.</p><button class="driver-button" :disabled="busy">تأكيد استلام المبلغ</button></form></section><section v-if="order.history?.length" class="driver-card"><h2>سجل التوصيل</h2><ol class="driver-timeline"><li v-for="(item,index) in order.history" :key="index"><strong>{{ deliveryLabels[item.to_status] }}</strong><p>{{ item.actor }}<span v-if="item.reason"> · {{ item.reason }}</span></p><small>{{ driverTime(item.at) }}</small></li></ol></section></template></main></template>
